import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.OutputStream;
import java.net.InetSocketAddress;
import java.net.Socket;
import java.net.SocketTimeoutException;
import java.nio.ByteBuffer;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.nio.channels.ServerSocketChannel;
import java.nio.channels.SocketChannel;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Iterator;
import java.util.List;
import java.util.Scanner;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;

// 준비 코드: 연결 하나의 상태예요. pending에는 아직 다 오지 않은 프레임의 앞부분이 쌓여요.
static class Conn {
    final int id;
    final ByteArrayOutputStream pending = new ByteArrayOutputStream();
    final List<String> frames = new ArrayList<>();
    Conn(int id) { this.id = id; }
}
static final List<Conn> conns = Collections.synchronizedList(new ArrayList<>());
// 준비 코드(시험용 신호): 서버가 연결 1의 첫 바이트를 읽으면 열려요. 시험 클라이언트는 이 신호 뒤에 B를 연결해요.
static final CountDownLatch firstRead = new CountDownLatch(1);
static volatile boolean running = true;

// 준비 코드: 지금 읽을 수 있는 바이트만 읽어 pending 뒤에 붙여요. 상대가 닫았으면 -1이에요.
static int readAvailable(SocketChannel ch, Conn conn) throws IOException {
    ByteBuffer buf = ByteBuffer.allocate(64);
    int n = ch.read(buf);
    if (n > 0) {
        conn.pending.write(buf.array(), 0, n);
        if (conn.id == 1) firstRead.countDown();
    }
    return n;
}

// 준비 코드: 프레임은 길이 1바이트 + 본문이에요. pending 앞에 완성된 프레임이 있는지 봐요.
static boolean hasFrame(Conn conn) {
    byte[] b = conn.pending.toByteArray();
    return b.length > 0 && b.length >= 1 + b[0];
}

// 준비 코드: 완성된 프레임을 모두 꺼내고, 남은 앞부분은 pending에 그대로 둬요.
static List<String> takeFrames(Conn conn) {
    byte[] b = conn.pending.toByteArray();
    List<String> out = new ArrayList<>();
    int i = 0;
    while (i < b.length && i + 1 + b[i] <= b.length) {
        out.add(new String(b, i + 1, b[i], StandardCharsets.UTF_8));
        i += 1 + b[i];
    }
    conn.pending.reset();
    conn.pending.write(b, i, b.length - i);
    return out;
}

static void reply(SocketChannel ch, Conn conn, String body) throws IOException {
    conn.frames.add(body);
    ch.write(ByteBuffer.wrap(("OK " + body.toUpperCase() + "\n").getBytes(StandardCharsets.UTF_8)));
}

// 이벤트 루프가 "이 연결에서 읽을 수 있어요"라는 알림을 받으면 실행돼요.
// 이 메서드가 돌아오기 전에는 같은 스레드의 다른 연결을 처리하지 못해요.
static void onReadable(SocketChannel ch, Conn conn) throws IOException {
    if (readAvailable(ch, conn) < 0) { ch.close(); return; }
    // 고칠 곳: 프레임이 다 올 때까지 여기서 계속 읽으며 기다려요.
    while (!hasFrame(conn)) {
        if (readAvailable(ch, conn) < 0) { ch.close(); return; }
    }
    for (String body : takeFrames(conn)) reply(ch, conn, body);
}

// 준비 코드: 스레드 하나로 모든 연결을 돌보는 이벤트 루프예요.
static void serve(ServerSocketChannel server) {
    try (Selector selector = Selector.open()) {
        server.configureBlocking(false);
        server.register(selector, SelectionKey.OP_ACCEPT);
        while (running) {
            selector.select(100);
            Iterator<SelectionKey> keys = selector.selectedKeys().iterator();
            while (keys.hasNext()) {
                SelectionKey key = keys.next();
                keys.remove();
                if (!key.isValid()) continue;
                if (key.isAcceptable()) {
                    SocketChannel ch = server.accept();
                    if (ch == null) continue;
                    ch.configureBlocking(false);
                    Conn conn = new Conn(conns.size() + 1);
                    conns.add(conn);
                    ch.register(selector, SelectionKey.OP_READ, conn);
                } else if (key.isReadable()) {
                    onReadable((SocketChannel) key.channel(), (Conn) key.attachment());
                }
            }
        }
    } catch (IOException e) {
        System.out.println("서버 오류 " + e.getMessage());
    }
}

// 준비 코드(시험 클라이언트): 응답 한 줄을 2초까지 기다려요. 시간 제한은 멈춤을 찾는 용도예요.
static String readLine(Socket s) throws IOException {
    InputStream in = s.getInputStream();
    StringBuilder line = new StringBuilder();
    try {
        for (int c = in.read(); c != -1 && c != '\n'; c = in.read()) line.append((char) c);
    } catch (SocketTimeoutException e) {
        return "시간 초과 2초 안에 응답이 없어요";
    }
    return line.toString();
}

static void send(Socket s, byte[] bytes) throws IOException {
    OutputStream out = s.getOutputStream();
    out.write(bytes);
    out.flush();
}

void main() throws Exception {
    Scanner in = new Scanner(System.in);
    String scenario = in.hasNextLine() ? in.nextLine().trim() : "";
    ServerSocketChannel server = ServerSocketChannel.open();
    // 127.0.0.1에만 열고 포트 0을 주면 운영체제가 빈 포트를 골라요. 실행할 때마다 달라질 수 있어요.
    server.bind(new InetSocketAddress("127.0.0.1", 0));
    int port = ((InetSocketAddress) server.getLocalAddress()).getPort();
    Thread loop = Thread.ofPlatform().start(() -> serve(server));
    try (Socket a = new Socket("127.0.0.1", port)) {
        a.setSoTimeout(2000);
        send(a, new byte[]{5, 'h'});
        System.out.println("A 보냄 | 앞 2바이트 길이 5 중 본문 1글자");
        if (!firstRead.await(2, TimeUnit.SECONDS)) System.out.println("서버가 A를 읽지 못했어요");
        try (Socket b = new Socket("127.0.0.1", port)) {
            b.setSoTimeout(2000);
            if (scenario.equals("two")) {
                send(b, new byte[]{2, 'h', 'i', 2, 'y', 'o'});
                System.out.println("B 보냄 | 완전한 메시지 두 개 hi yo");
                System.out.println("B 응답 | " + readLine(b));
                System.out.println("B 응답 | " + readLine(b));
            } else {
                send(b, new byte[]{2, 'h', 'i'});
                System.out.println("B 보냄 | 완전한 메시지 hi");
                System.out.println("B 응답 | " + readLine(b));
            }
            send(a, "ello".getBytes(StandardCharsets.UTF_8));
            System.out.println("A 보냄 | 나머지 4바이트");
            System.out.println("A 응답 | " + readLine(a));
        }
    }
    running = false;
    loop.join(3000);
    server.close();
    for (Conn c : conns) System.out.println("서버 연결 " + c.id + " | 처리한 프레임 " + c.frames);
}

